// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));

        bool ok;
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
